(()=>{
   //根据url获取下一页nextBaseUrl的nextPage 
   if (/\?page=\d+/.test(baseUrl)) {
      nextPage = parseInt(baseUrl.match(/page=(\d+)/)[1])+1;
   } else {
      nextPage =2
   }
   //根据result的区别判断是否加载下一页
   if (result.includes('id="linkNext"')) {
      //置null,否则会尝试执行
      nextBaseUrl = null;
  } else {
      nextBaseUrl = baseUrl.replace(/\?page=\d+/, '')+"?page="+nextPage;
  }
})()
